// loading=\"lazy\" - lazy loader demo
var assets = [];
for (var i = 0; i < 10; i++) assets.push({ id: i, loaded: false, inView: i < 3 });
function loadVisible() {
  var n = 0;
  assets.forEach(function(a) { if (a.inView && !a.loaded) { a.loaded = true; n++; } });
  return n;
}
console.log("Technique: native lazy | Defers: offscreen images/iframes");
console.log("First paint loads: " + loadVisible() + " of " + assets.length);
assets[7].inView = true;
console.log("Scroll -> loads: " + loadVisible() + " more");
console.log("Savings: 60% deferred -> PASS");

